SET	@prov_c := '%s';
SET	@id:= '%s';
SET @cat_id := '%s';
SET @send :=  IF((SELECT active FROM sys_report WHERE cat_id = @cat_id and id = @id )=1,0,2);
SET	@b_year:=(SELECT yearprocess FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');
SET @end_d:=concat(@b_year,'0930');

CREATE TABLE IF NOT EXISTS s_dm_screen_pop_age(
  id varchar(32) NOT NULL,
  hospcode varchar(5) NOT NULL,
  areacode varchar(8) NOT NULL,
  flag_sent varchar(1) DEFAULT NULL,
  date_com varchar(14) DEFAULT NULL,
  b_year varchar(4) NOT NULL,
	pop_group2 int(9) DEFAULT 0,
	result_group2 int(9) DEFAULT 0,
	pop_group3 int(9) DEFAULT 0,
	result_group3 int(9) DEFAULT 0,
	pop_group4 int(9) DEFAULT 0,
	result_group4 int(9) DEFAULT 0,

	pop_group2_1 int(9) DEFAULT 0,
	result_group2_1 int(9) DEFAULT 0,
	pop_group2_2 int(9) DEFAULT 0,
	result_group2_2 int(9) DEFAULT 0,

	pop_group3_1 int(9) DEFAULT 0,
	result_group3_1 int(9) DEFAULT 0,
	pop_group3_2 int(9) DEFAULT 0,
	result_group3_2 int(9) DEFAULT 0,

	pop_group4_1 int(9) DEFAULT 0,
	result_group4_1 int(9) DEFAULT 0,
	pop_group4_2 int(9) DEFAULT 0,
	result_group4_2 int(9) DEFAULT 0,

	PRIMARY KEY (id,hospcode,areacode,b_year),
	KEY (hospcode),
	KEY (areacode),
	KEY (b_year)
) ENGINE=MyISAM DEFAULT CHARSET=utf8;

CALL AddCol('hdc','s_dm_screen_pop_age','pop_group2_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group2_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','pop_group2_2','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group2_2','int(9) DEFAULT 0 ');

CALL AddCol('hdc','s_dm_screen_pop_age','pop_group3_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group3_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','pop_group3_2','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group3_2','int(9) DEFAULT 0 ');

CALL AddCol('hdc','s_dm_screen_pop_age','pop_group4_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group4_1','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','pop_group4_2','int(9) DEFAULT 0 ');
CALL AddCol('hdc','s_dm_screen_pop_age','result_group4_2','int(9) DEFAULT 0 ');

DELETE FROM s_dm_screen_pop_age WHERE id=@id AND b_year=(@b_year+543);

INSERT IGNORE INTO s_dm_screen_pop_age 
(
SELECT
	@id,p.hospcode,p.areacode,@send,DATE_FORMAT(now(),'%Y%m%d%H%i') as d_com,@b_year+543 as b_year
	,b2,a2,b3,a3,b4,a4
	,b2_1,a2_1,b2_2,a2_2
	,b3_1,a3_1,b3_2,a3_2
  ,b4_1,a4_1,b4_2,a4_2
FROM
(SELECT
	s.hospcode,s.areacode
						,COUNT(DISTINCT if(ca.groupcode3560 ='2', s.cid,null)) as b2
						,COUNT(DISTINCT if(ca.groupcode3560 ='3', s.cid,null)) as b3
						,COUNT(DISTINCT if(ca.groupcode3560 ='4', s.cid,null)) as b4
						,COUNT(DISTINCT if(groupcode3560='2' AND s.date_screen is not null AND risk in(0,1,2) , s.cid,null))  as a2
						,COUNT(DISTINCT if(groupcode3560='3' AND s.date_screen is not null AND risk in(0,1,2) , s.cid,null)) as a3
						,COUNT(DISTINCT if(groupcode3560='4' AND s.date_screen is not null AND risk in(0,1,2) , s.cid,null)) as a4

						,COUNT(DISTINCT if(ca.groupcode3560 ='2' AND pe.sex=1, s.cid,null)) as b2_1
						,COUNT(DISTINCT if(ca.groupcode3560 ='3' AND pe.sex=1, s.cid,null)) as b3_1
						,COUNT(DISTINCT if(ca.groupcode3560 ='4' AND pe.sex=1, s.cid,null)) as b4_1
						,COUNT(DISTINCT if(groupcode3560='2' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=1 , s.cid,null))  as a2_1
						,COUNT(DISTINCT if(groupcode3560='3' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=1, s.cid,null)) as a3_1
						,COUNT(DISTINCT if(groupcode3560='4' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=1, s.cid,null)) as a4_1

						,COUNT(DISTINCT if(ca.groupcode3560 ='2' AND pe.sex=2, s.cid,null)) as b2_2
						,COUNT(DISTINCT if(ca.groupcode3560 ='3' AND pe.sex=2, s.cid,null)) as b3_2
						,COUNT(DISTINCT if(ca.groupcode3560 ='4' AND pe.sex=2, s.cid,null)) as b4_2
						,COUNT(DISTINCT if(groupcode3560='2' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=2 , s.cid,null))  as a2_2
						,COUNT(DISTINCT if(groupcode3560='3' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=2, s.cid,null)) as a3_2
						,COUNT(DISTINCT if(groupcode3560='4' AND s.date_screen is not null AND risk in(0,1,2) AND pe.sex=2, s.cid,null)) as a4_2

	FROM
	t_person_dm_screen s INNER JOIN t_person_cid pe ON s.cid=pe.cid
		LEFT JOIN cage ca ON s.age_y=ca.age
	WHERE substr(s.areacode,1,2)=@prov_c
	GROUP BY s.hospcode,s.areacode
) p
);
